293: async function executeSubmitToIndex(targetUrl) {
294:   let url;
295:   try { url = new URL(targetUrl); } catch (err) {
296:     return { ok: false, error: 'invalid_url', detail: err.message };
297:   }
298:   // Only http(s); refuse file:, ftp:, etc.
299:   if (url.protocol !== 'http:' && url.protocol !== 'https:') {
300:     return { ok: false, error: 'unsupported_protocol', protocol: url.protocol };
301:   }
302:   const driver = url.protocol === 'https:'
303:     ? await import('https')
304:     : await import('http');
305:   return await new Promise((resolve) => {
306:     const req = driver.request(
307:       url,
308:       { method: 'GET', timeout: 1500, headers: { 'user-agent': 'dvaa-exfil-canary' } },
309:       (res) => {
310:         // Drain so the connection closes.
311:         res.on('data', () => {});
312:         res.on('end', () => resolve({ ok: true, statusCode: res.statusCode }));
313:       },
314:     );
315:     req.on('timeout', () => { req.destroy(); resolve({ ok: false, error: 'timeout' }); });
316:     req.on('error', (e) => resolve({ ok: false, error: e.code || 'request_error', detail: e.message }));
317:     req.end();
318:   });
319: }

